import copy,json
from work import evaluate
with open('requests.json') as f: requests=json.load(f)
with open('evidence.json') as f: evidence=json.load(f)
with open('policy.json') as f: policy=json.load(f)
with open('report.json') as f: report=json.load(f)
actual=[evaluate(r,evidence,policy) for r in requests]
assert actual == report, (actual, report)
# Missing required conditions are sorted and take precedence.
r={'claim':'c','conditions':{}}; e=[]; p={'required_conditions':['z','a']}
assert evaluate(r,e,p)=={'status':'unknown','value':None,'sources':[],'unknowns':['a','z']}
# Exercise claim, withdrawal, required-condition, and verification filters.
r={'claim':'c','conditions':{'x':1,'irrelevant':'q'}}
e=[{'source':'wrong-claim','claim':'d','value':7,'conditions':{'x':1},'verified':True},{'source':'withdrawn','claim':'c','value':7,'conditions':{'x':1},'withdrawn':True,'verified':True},{'source':'wrong-condition','claim':'c','value':7,'conditions':{'x':2},'verified':True},{'source':'unverified','claim':'c','value':7,'conditions':{'x':1},'verified':False},{'source':'good','claim':'c','value':7,'conditions':{'x':1},'verified':True}]
p={'required_conditions':['x'],'require_verified':True}
before=copy.deepcopy((r,e,p))
assert evaluate(r,e,p)=={'status':'supported','value':7,'sources':['good'],'unknowns':[]}
assert (r,e,p)==before
# Eligible superseding records remove superseded IDs; canonical object key order agrees.
e=[{'source':'old','claim':'c','value':{'a':1,'b':2},'conditions':{'x':1}},{'source':'new','claim':'c','value':{'b':2,'a':1},'conditions':{'x':1},'supersedes':['old']}]
assert evaluate(r,e,{'required_conditions':['x']})=={'status':'supported','value':{'b':2,'a':1},'sources':['new'],'unknowns':[]}
# Ineligible superseders have no effect; disagreement conflicts without voting.
e=[{'source':'a','claim':'c','value':1,'conditions':{'x':1}},{'source':'b','claim':'c','value':2,'conditions':{'x':1}},{'source':'c','claim':'c','value':2,'conditions':{'x':1}},{'source':'bad','claim':'c','value':2,'conditions':{'x':2},'supersedes':['a']}]
assert evaluate(r,e,{'required_conditions':['x']})=={'status':'conflict','value':None,'sources':['a','b','c'],'unknowns':['source disagreement']}
# Boolean false alone is unsupported, and absent evidence stays unknown rather than zero.
assert evaluate(r,[{'source':'f','claim':'c','value':False,'conditions':{'x':1}}],{'required_conditions':['x']})=={'status':'unsupported','value':False,'sources':['f'],'unknowns':[]}
assert evaluate({'claim':'none','conditions':{'x':1}},e,{'required_conditions':['x']})=={'status':'unknown','value':None,'sources':[],'unknowns':['no matching evidence']}
print(json.dumps(actual,sort_keys=True))

